+#[test]
+fn preserve_climb_reverses_the_pass_between_entry_and_retract() {
+    let src = contour();
+    let out = mirror_plane(&src, x5(), MirrorMode::PreserveClimb(PassFamily::Contour)).expect("a contour reverses");
+    assert!(out.is_chained());
