+    let sweep = if sweep == 0.0 { std::f64::consts::TAU } else { sweep };
+    let step = sweep / count.max(1) as f64;
+    if ra == rb {
+        let s = (step * 0.25).sin();
+        ra * (2.0 * s * s)
+    } else {
+        // For radius linear in angle: |p''| <= hypot(r, 2*|dr/dtheta|).
+        ra.max(rb).hypot(2.0 * (rb - ra).abs() / sweep) * step * step / 8.0
+    }
